SELECT o.id, o.order_no, o.amount, o.status, o.created_at, o.finished_at, i.id AS item_id, i.title AS item_title, i.image_url AS item_image, i.price AS item_price, o.buyer_id, bu.nickname AS buyer_nickname, o.seller_id, su.nickname AS seller_nickname FROM t_order o JOIN t_item i ON i.id = o.item_id JOIN t_user bu ON bu.id = o.buyer_id JOIN t_user su ON su.id = o.seller_id
o.buyer_id = #{userId} o.seller_id = #{userId}
ORDER BY o.created_at DESC

SELECT o.id, o.order_no, o.amount, o.status, o.created_at, o.finished_at, i.id AS item_id, i.title AS item_title, i.image_url AS item_image, i.price AS item_price, o.buyer_id, bu.nickname AS buyer_nickname, o.seller_id, su.nickname AS seller_nickname FROM t_order o JOIN t_item i ON i.id = o.item_id JOIN t_user bu ON bu.id = o.buyer_id JOIN t_user su ON su.id = o.seller_id
AND o.status = #{status}
ORDER BY o.created_at DESC
